function firstFreeAfterPrefix(nums: number[]): number {
  let s = nums[0];
  for (let i = 1; i < nums.length && nums[i] === nums[i - 1] + 1; i++) s += nums[i];
  let x = s;
  while (nums.includes(x)) x++;
  return x;
}

